413	     *
414	     * @param name to test
415	     * @return true if pet name is already in use
416	     */
417	    public Pet getPet(String name, boolean ignoreNew) {
418	        name = name.toLowerCase();
419	        for (Pet pet : getPetsInternal()) {
420	            if (!ignoreNew || !pet.isNew()) {
421	                String compName = pet.getName();
422	                compName = compName.toLowerCase();
423	                if (compName.equals(name)) {
424	                    return pet;
425	                }
426	            }
427	        }
428	        return null;
429	    }
