435	    @Override
436	    public String toString() {
437	        return new ToStringCreator(this)
438	
439	            .append("id", this.getId())
440	            .append("new", this.isNew())
441	            .append("lastName", this.getLastName())
442	            .append("firstName", this.getFirstName())
443	            .append("address", this.address)
444	            .append("city", this.city)
445	            .append("telephone", this.telephone)
446	            .toString();
447	    }
448	}
